<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>PKcards — Table vivante</title>
<style>
@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@600;700&family=DM+Mono:wght@400;500&family=Outfit:wght@400;500;600;700&display=swap');
:root{--felt:#132940;--felt2:#0d1a2c;--ivory:#f8f2e6;--heart:#f05b58;--diamond:#f3bc45;--club:#34b67b;--spade:#8db9ff;--ink:#0b1828;--mono:'DM Mono',monospace;--display:'Barlow Condensed',sans-serif;--body:'Outfit',sans-serif}*{box-sizing:border-box}body{margin:0;min-height:100dvh;background:radial-gradient(circle at 50% 35%,#244d68 0,var(--felt) 40%,var(--felt2) 100%);color:var(--ivory);font-family:var(--body);overflow-x:hidden}body:before{content:'';position:fixed;inset:0;opacity:.22;pointer-events:none;background-image:radial-gradient(#fff 0.6px,transparent .6px);background-size:5px 5px;mix-blend-mode:overlay}.shell{position:relative;min-height:100dvh;max-width:680px;margin:auto;padding:calc(18px + env(safe-area-inset-top)) 18px calc(24px + env(safe-area-inset-bottom));display:flex;flex-direction:column}.top{display:flex;align-items:center;justify-content:space-between;position:relative;z-index:3}.brand{font:500 .76rem var(--mono);letter-spacing:.08em;text-transform:uppercase}.brand b{font:700 1.1rem var(--display);letter-spacing:0;color:var(--heart)}.round{display:grid;place-items:center;width:44px;height:44px;border:1px solid rgba(248,242,230,.45);border-radius:50%;background:rgba(255,255,255,.07);color:inherit;text-decoration:none;font:1.1rem var(--mono)}.home{flex:1;display:flex;flex-direction:column;justify-content:center}.eyebrow{margin:30px 0 10px;color:var(--diamond);font:.65rem var(--mono);letter-spacing:.12em;text-transform:uppercase}.home h1,.game-title{margin:0;font:700 clamp(4.3rem,17vw,7rem)/.75 var(--display);letter-spacing:-.045em;text-transform:uppercase}.home h1 span{display:block;color:var(--heart)}.prompt{max-width:300px;margin:26px 0 24px;font-size:1rem;line-height:1.4}.filters{display:flex;gap:8px;overflow:auto;padding:5px 2px 16px;scrollbar-width:none}.filter{white-space:nowrap;border:1px solid rgba(248,242,230,.35);border-radius:999px;padding:8px 12px;background:transparent;color:var(--ivory);font:.66rem var(--mono)}.filter.active{background:var(--ivory);border-color:var(--ivory);color:var(--ink)}.table{position:relative;height:min(48vh,390px);min-height:315px;margin:0 -7px}.table:before{content:'';position:absolute;inset:18% 4% 2%;border:1px solid rgba(248,242,230,.17);border-radius:50%;box-shadow:inset 0 0 60px rgba(0,0,0,.2)}.hand-card{position:absolute;left:50%;top:50%;width:min(49vw,245px);height:min(65vw,325px);padding:13px;border:0;border-radius:15px;background:var(--ivory);color:var(--ink);box-shadow:0 20px 35px rgba(0,0,0,.35);text-align:left;text-decoration:none;overflow:hidden;transform-origin:50% 120%;transition:transform .5s cubic-bezier(.2,.9,.2,1),filter .25s}.hand-card:before{content:'';position:absolute;inset:8px;border:1px solid #b9c2ca;border-radius:9px;background:linear-gradient(135deg,transparent 48%,rgba(19,41,64,.05) 48% 52%,transparent 52%)}.hand-card>*{position:relative;z-index:1}.card-face{position:absolute!important;right:-17%;bottom:-11%;z-index:0!important;width:73%;opacity:.38;transform:rotate(14deg);mix-blend-mode:multiply}.hand-card:nth-child(1){transform:translate(-80%,-48%) rotate(-14deg)}.hand-card:nth-child(2){transform:translate(-50%,-54%) rotate(0deg);z-index:2}.hand-card:nth-child(3){transform:translate(-20%,-48%) rotate(14deg)}.hand-card:hover{filter:brightness(1.05)}.suit{font:2.5rem/1 var(--display)}.s1{color:var(--heart)}.s2{color:var(--club)}.s3{color:var(--diamond)}.card-meta{display:block;margin-top:25%;font:.57rem var(--mono);letter-spacing:.07em;text-transform:uppercase}.hand-card h2{margin:7px 0;font:700 clamp(2rem,8vw,3.8rem)/.78 var(--display);letter-spacing:-.04em;text-transform:uppercase}.card-count{font:.65rem var(--mono);color:#526073}.deal{align-self:center;position:relative;z-index:3;border:0;border-radius:999px;background:var(--heart);color:var(--ink);padding:17px 25px;box-shadow:0 5px 0 #8c292f;font:700 .78rem var(--mono);letter-spacing:.08em;text-transform:uppercase}.deal:active{transform:translateY(4px);box-shadow:0 1px 0 #8c292f}.hint{text-align:center;margin:18px 0 0;color:#b9cad8;font:.58rem var(--mono);letter-spacing:.08em;text-transform:uppercase}.search-sheet{position:fixed;z-index:9;left:0;right:0;bottom:0;padding:20px 18px calc(20px + env(safe-area-inset-bottom));background:var(--ivory);color:var(--ink);transform:translateY(105%);transition:transform .3s ease;border-radius:25px 25px 0 0}.search-sheet.open{transform:none}.sheet-head{display:flex;align-items:center;justify-content:space-between}.search-sheet input{width:100%;margin:18px 0 10px;border:1px solid var(--ink);border-radius:8px;padding:14px;background:#fff;font:1rem var(--body)}.results{max-height:45dvh;overflow:auto}.result{display:flex;justify-content:space-between;padding:13px 0;border-bottom:1px solid #d5d0c5;color:inherit;text-decoration:none}.result small{font:var(--mono);color:#57616c}.reader{padding-top:25px}.reader .eyebrow{margin-top:26px}.names{display:flex;gap:7px;overflow:auto;margin:25px 0 21px;padding-bottom:4px}.name{flex:0 0 auto;border:1px solid rgba(248,242,230,.35);border-radius:999px;padding:7px 10px;font:.65rem var(--mono)}.versions{display:flex;gap:8px;overflow:auto;margin:0 -18px;padding:0 18px 15px;scrollbar-width:none}.version{flex:0 0 auto;border:1px solid rgba(248,242,230,.45);border-radius:8px;padding:10px 12px;color:var(--ivory);text-decoration:none;font:.64rem var(--mono);text-transform:uppercase}.version.on{background:var(--diamond);border-color:var(--diamond);color:var(--ink)}.rule-card{position:relative;margin:3px -18px 0;padding:28px 20px 45px;background:var(--ivory);color:var(--ink);border-radius:26px 26px 0 0;min-height:55vh}.rule-card:before{content:'RÈGLE EN MAIN';display:block;margin-bottom:20px;color:var(--heart);font:.62rem var(--mono);letter-spacing:.11em}.rule-card p{font-size:1.06rem;line-height:1.62}.rule-card h2{margin:34px 0 12px;font:700 2.2rem/.9 var(--display);text-transform:uppercase}.rule-card h3{font:700 1.45rem var(--display)}.rule-card a{color:#075d6e}.rule-note{margin:-1px -18px 18px;padding:10px 18px;background:rgba(243,188,69,.18);color:var(--ivory);font:.62rem var(--mono)}@media(prefers-reduced-motion:reduce){*{transition:none!important}}
</style><body><main class="shell">
<header class="top"><a class="brand" href="?"><b>PK</b> / table vivante</a><button class="round" id="searchOpen" aria-label="Rechercher un jeu">⌕</button></header>
<?php if(!$slug): ?><section class="home"><p class="eyebrow">Choisis une main, pas un catalogue</p><h1>Quel jeu<br><span>ce soir ?</span></h1><p class="prompt">Règle rapide, grande tablée ou duel tactique : tire trois idées de la table.</p><div class="filters"><button class="filter active">À 2–4</button><button class="filter">≤ 30 min</button><button class="filter">Sans prise de tête</button><button class="filter">Stratégie</button></div><div class="table" id="table"><?php $suits=['♥','♣','♦']; $faces=['01-coeur.png','V-pique.png','D-carreau.png']; foreach($deal as $i=>$g): ?><a class="hand-card" href="?game=<?=e($g['slug'])?>"><img class="card-face" src="?card=<?=$faces[$i]?>" alt="" aria-hidden="true"><span class="suit s<?= $i+1 ?>"><?=$suits[$i]?></span><span class="card-meta"><?=e($g['category'] ?: 'jeu')?> · <?=e($g['players'] ?: 'tous joueurs')?></span><h2><?=e($g['title'])?></h2><span class="card-count"><?=$g['version_count']?> version<?= $g['version_count']>1?'s':''?> à explorer</span></a><?php endforeach;?></div><button class="deal" id="deal">↻ Distribuer trois jeux</button><p class="hint">Touchez une carte pour l’ouvrir</p></section>
<?php else: ?><section class="reader"><a class="round" href="?" aria-label="Retour">←</a><p class="eyebrow"><?=e($game['category'] ?: 'jeu')?> · une fiche, plusieurs traditions</p><h1 class="game-title"><?=e($game['title'])?></h1><div class="names"><?php foreach($names as $n):?><span class="name"><?=e($n['name'])?> · <?=e($n['language'])?></span><?php endforeach;?></div><nav class="versions" aria-label="Versions de la règle"><?php foreach($versions as $v):?><a class="version <?=$current&&$v['id']==$current['id']?'on':''?>" href="?game=<?=e($slug)?>&version=<?=$v['id']?>"><?=e($v['source'])?> · <?=e($v['language'])?><?=$v['status']==='primary'?' ★':''?></a><?php endforeach;?></nav><?php if($current):?><p class="rule-note">Version <?=e($current['status'])?> · balayez les onglets pour comparer les rédactions</p><article class="rule-card"><?=html(Library::content($current['markdown_path']))?></article><?php else:?><article class="rule-card"><p>Cette fiche attend encore sa première règle liée.</p></article><?php endif;?></section><?php endif;?></main>
<aside class="search-sheet" id="sheet" aria-label="Recherche"><div class="sheet-head"><b>Retrouver un jeu</b><button class="round" id="searchClose">×</button></div><form><input name="q" value="<?=e($q)?>" placeholder="Belote, Bela, Klaberjass…" autofocus></form><div class="results"><?php foreach(array_slice($games,0,35) as $g):?><a class="result" href="?game=<?=e($g['slug'])?>"><span><?=e($g['title'])?></span><small><?=$g['version_count']?> règles</small></a><?php endforeach;?></div></aside>
<script>const sheet=document.querySelector('#sheet'),open=document.querySelector('#searchOpen'),close=document.querySelector('#searchClose');open?.addEventListener('click',()=>sheet.classList.add('open'));close?.addEventListener('click',()=>sheet.classList.remove('open'));document.querySelector('#deal')?.addEventListener('click',()=>{const cards=[...document.querySelectorAll('.hand-card')];cards.forEach((c,i)=>{c.style.transform=`translate(-50%,-45%) rotate(${(i-1)*3}deg) scale(.82)`});setTimeout(()=>location.href='?',380)});</script></body></html>
